def compute(vars):
    silver_2019 = vars["v1"]
    silver_2018 = vars["v2"]
    value = 2019 if silver_2019 > silver_2018 else 2018 if silver_2018 > silver_2019 else None
    return {
        "value": value,
        "trace": {
            "silver_2019": silver_2019,
            "silver_2018": silver_2018,
            "comparison": "larger",
            "output_meta": {"currency": None, "scale": None, "unit": "year"}
        }
    }
